// Replace with the HTTPS base URL of YOUR n8n instance. No trailing slash.
const baseUrl = 'https://YOUR-N8N-HOST.example';
return $input.all().map(item => ({json:{...item.json,calendarApiUrl:baseUrl.replace(/\/$/,'')+'/webhook/dental-receptionist-calendar-v1'}}));

const text=String($json.data || '').trim();
if (!text || text.length > 200000) throw new Error('Upload a non-empty UTF-8 .txt file containing at most 200,000 characters.');
return [{json:{text}}];

// EDIT THIS CONFIGURATION. Calendar is used for BOTH checking and booking.
const config = {
  calendarId: 'REPLACE_WITH_GOOGLE_CALENDAR_ID',
  timezone: 'America/New_York',
  openingHour: 9, closingHour: 17, slotMinutes: 30,
  workingDays: [1,2,3,4,5], // Monday=1 ... Sunday=7
  minLeadMinutes: 60, maxAdvanceDays: 90
};
const out = (status,message,httpStatus=400) => [{json:{valid:false,result:{success:false,status,message},httpStatus}}];
// Native Intl avoids reliance on external npm packages in n8n Code nodes.
function localParts(ms,tz) {
 const p=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:tz,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(new Date(ms)).map(x=>[x.type,x.value]));
 return {y:+p.year,m:+p.month,d:+p.day,h:+p.hour,min:+p.minute,s:+p.second};
}
function zonedMs(y,m,d,h,min,tz) {
 const wall=Date.UTC(y,m-1,d,h,min); const matches=new Set();
 for (const shift of [-86400000,0,86400000]) {
  const sample=wall+shift,p=localParts(sample,tz);
  const offset=Date.UTC(p.y,p.m-1,p.d,p.h,p.min,p.s)-sample;
  const candidate=wall-offset, c=localParts(candidate,tz);
  if(c.y===y&&c.m===m&&c.d===d&&c.h===h&&c.min===min)matches.add(candidate);
 }
 if(matches.size!==1)throw new Error('Ambiguous or nonexistent local time. Choose another date/time.');
 return [...matches][0];
}
try {
 if(config.calendarId.startsWith('REPLACE_')) return out('configuration_required','Administrator must configure the clinic calendar.',503);
 const now=Date.now(),today=localParts(now,config.timezone);
 if(!Number.isInteger(config.slotMinutes)||config.slotMinutes<5||config.slotMinutes>240||config.openingHour<0||config.closingHour>23||config.closingHour<=config.openingHour) return out('configuration_error','Invalid clinic opening hours or slot duration.',503);
 let b=$json.body;
 if(typeof b==='string'){try{b=JSON.parse(b)}catch{return out('invalid_request','Send a JSON object.');}}
 if(!b||typeof b!=='object'||Array.isArray(b))return out('invalid_request','Send a JSON object.');
 if(!['availability','book'].includes(b.action))return out('invalid_action','action must be availability or book.');
 if(typeof b.date!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(b.date))return out('invalid_date','Use YYYY-MM-DD.');
 const [y,m,d]=b.date.split('-').map(Number),day=new Date(Date.UTC(y,m-1,d));
 if(day.getUTCFullYear()!==y||day.getUTCMonth()!==m-1||day.getUTCDate()!==d)return out('invalid_date','Date does not exist.');
 const delta=(Date.UTC(y,m-1,d)-Date.UTC(today.y,today.m-1,today.d))/86400000;
 if(delta<0||delta>config.maxAdvanceDays)return out('outside_booking_window','Choose today or a date within '+config.maxAdvanceDays+' days.');
 const context={timezone:config.timezone,clinicToday:[today.y,String(today.m).padStart(2,'0'),String(today.d).padStart(2,'0')].join('-'),date:b.date,slotMinutes:config.slotMinutes};
 if(!config.workingDays.includes(day.getUTCDay()||7))return [{json:{valid:false,httpStatus:b.action==='book'?409:200,result:{success:b.action==='availability',status:'closed',...context,availableSlots:[],message:'Clinic is closed on this weekday.'}}}];
 const start=zonedMs(y,m,d,config.openingHour,0,config.timezone),end=zonedMs(y,m,d,config.closingHour,0,config.timezone);
 const slots=[];
 for(let s=start;s+config.slotMinutes*60000<=end;s+=config.slotMinutes*60000){
  if(s<now+config.minLeadMinutes*60000)continue;
  const p=localParts(s,config.timezone);
  slots.push({time:String(p.h).padStart(2,'0')+':'+String(p.min).padStart(2,'0'),start:new Date(s).toISOString(),end:new Date(s+config.slotMinutes*60000).toISOString()});
 }
 let booking=null;
 if(b.action==='book'){
  if(b.confirmed!==true)return out('confirmation_required','Patient confirmation is required.');
  if(typeof b.name!=='string'||b.name.trim().length<2||b.name.length>100||/[\r\n<>]/.test(b.name))return out('invalid_name','Provide a valid patient name (2–100 characters).');
  if(typeof b.email!=='string'||b.email.length>254||!/^[^\s@<>]+@[^\s@<>]+\.[^\s@<>]+$/.test(b.email))return out('invalid_email','Provide a valid email address.');
  if(typeof b.time!=='string'||!/^\d{2}:\d{2}$/.test(b.time))return out('invalid_time','Use HH:mm.');
  const slot=slots.find(s=>s.time===b.time);
  if(!slot)return out('invalid_slot','Choose an offered slot within clinic hours and minimum lead time.',409);
  booking={...slot,name:b.name.trim(),email:b.email.trim().toLowerCase()};
 }
 return [{json:{valid:true,config,context,action:b.action,slots,booking,freebusyRequest:{timeMin:new Date(start).toISOString(),timeMax:new Date(end).toISOString(),timeZone:config.timezone,items:[{id:config.calendarId}]}}}];
}catch(e){return out('validation_error','Unable to validate clinic date/time or configuration. Check the timezone and choose an unambiguous local time.');}

const request=$('Configure and Validate Calendar Request').first().json;
const r=$json,cal=r.body?.calendars?.[request.config.calendarId];
const fail=(status,message,httpStatus)=>[{json:{readyToBook:false,httpStatus,result:{success:false,status,message,...request.context}}}];
if(r.statusCode!==200||!cal||cal.errors?.length||!Array.isArray(cal.busy))return fail('calendar_unavailable','Could not verify calendar availability. Ask clinic staff to check.',502);
if(cal.busy.some(b=>!Number.isFinite(Date.parse(b.start))||!Number.isFinite(Date.parse(b.end))))return fail('calendar_unavailable','Calendar returned invalid busy times.',502);
const slots=request.slots.filter(s=>!cal.busy.some(b=>Date.parse(s.start)<Date.parse(b.end)&&Date.parse(s.end)>Date.parse(b.start)));
if(request.action==='availability')return [{json:{readyToBook:false,httpStatus:200,result:{success:true,status:'availability',...request.context,availableSlots:slots}}}];
if(!slots.some(s=>s.start===request.booking.start))return fail('slot_unavailable','This slot is no longer available. Check availability again.',409);
const b=request.booking;
// Deterministic slot ID reduces duplicate creation by this template; not a distributed lock.
const eventId='dental'+Date.parse(b.start).toString(16);
return [{json:{readyToBook:true,event:{id:eventId,summary:'Dental appointment',description:'Appointment arranged through the clinic receptionist.',start:{dateTime:b.start,timeZone:request.config.timezone},end:{dateTime:b.end,timeZone:request.config.timezone},attendees:[{email:b.email,displayName:b.name}],visibility:'private',guestsCanInviteOthers:false,guestsCanModify:false},calendarId:request.config.calendarId}}];

const r=$json, req=$('Configure and Validate Calendar Request').first().json;
if(r.statusCode>=200&&r.statusCode<300&&r.body?.id){return [{json:{httpStatus:201,result:{success:true,status:'booked',eventId:r.body.id,...req.context,time:req.booking.time,message:'Appointment created. Google Calendar was asked to send an invitation; email delivery is not verified.'}}}];}
const conflict=r.statusCode===409;
return [{json:{httpStatus:conflict?409:502,result:{success:false,status:conflict?'slot_conflict':'booking_outcome_unknown',message:conflict?'The slot ID already exists. Ask clinic staff to check the appointment before retrying.':'Booking was not confirmed. It may have reached Google Calendar. Ask clinic staff to check before retrying.'}}}];
